+const featuredProducts = [
+  {
+    name: "Relaxed Utility Jacket",
+    category: "Outerwear",
+    price: "$128.00",
+    tintStart: "#7d8d74",
+    tintEnd: "#d6d0c1",
+  },
+  {
+    name: "Cropped Wide-Leg Pant",
+    category: "Bottoms",
+    price: "$84.00",
+    tintStart: "#b7b0a5",
+    tintEnd: "#ebe4d9",
+  },
+  {
+    name: "Signature Knit Polo",
+    category: "Tops",
+    price: "$72.00",
+    tintStart: "#8c7b6d",
+    tintEnd: "#d9cec3",
+  },
+  {
+    name: "Everyday Leather Sneaker",
+    category: "Footwear",
+    price: "$110.00",
+    tintStart: "#4f5966",
+    tintEnd: "#c4ccd7",
+  },
+];
+
+const productGrid = document.getElementById("featured-products");
+
+productGrid.innerHTML = featuredProducts
+  .map(
+    (product) => `
+      <article class="product-card">
+        <div
+          class="product-visual"
+          style="--tint-start:${product.tintStart};--tint-end:${product.tintEnd};"
+        ></div>
+        <div class="product-meta">
+          <div>
+            <p class="story-meta">${product.category}</p>
+            <h3>${product.name}</h3>
+          </div>
+          <div class="price">${product.price}</div>
+        </div>
+      </article>
+    `
+  )
+  .join("");
+
+const countdown = document.getElementById("deal-countdown");
+let remainingSeconds = 12 * 60 * 60;
+
+function formatTime(seconds) {
+  const hours = String(Math.floor(seconds / 3600)).padStart(2, "0");
+  const minutes = String(Math.floor((seconds % 3600) / 60)).padStart(2, "0");
+  const secs = String(seconds % 60).padStart(2, "0");
+  return `${hours}:${minutes}:${secs}`;
+}
+
+function tick() {
+  countdown.textContent = formatTime(remainingSeconds);
+  if (remainingSeconds > 0) {
+    remainingSeconds -= 1;
+  }
+}
+
+tick();
+setInterval(tick, 1000);
+

')

